<?php
require_once __DIR__.'/../configuracion/admin-ui.php';require_once __DIR__.'/../configuracion/autentifica_admin.php';
$rows=app_rows('SELECT f.*,t.nombre_tipo_cat,COALESCE(n.servicios,0) AS servicios FROM tipos_iva_servicios f LEFT JOIN tipos_categorias t ON t.id_tipo=f.tipo_servicios LEFT JOIN (SELECT CATEGORIA,COUNT(*) AS servicios FROM tarifa GROUP BY CATEGORIA) n ON n.CATEGORIA=f.id_tipo_iva ORDER BY f.tipo_servicios,f.categoria');
$totalServices=0;foreach($rows as $r)$totalServices+=(int)$r['servicios'];
neo_page_start('Servicios y tarifas','Organiza las familias de servicios, consulta el IVA y accede a sus tarifas.','Facturación');
?>
<div class="neo-stats"><div class="neo-stat"><strong><?=count($rows)?></strong><span>Familias de servicios</span></div><div class="neo-stat"><strong><?=$totalServices?></strong><span>Servicios registrados</span></div></div>
<section class="neo-panel"><div class="neo-filters"><label class="grow">Localizar familia<input type="search" placeholder="Busca por nombre, categoría o IVA" data-neo-filter="neo-families"></label><a href="nueva_familia.php" class="neo-button">+ Nueva familia de servicios</a></div></section>
<?php if(app_value($_GET,'error')==='servicios'){ ?><p class="neo-panel" role="alert">Esta familia contiene servicios y no se puede eliminar. Revisa sus servicios antes de continuar.</p><?php } ?>
<div class="neo-table-wrap"><table class="neo-data-table" id="neo-families"><thead><tr><th>Familia de servicios</th><th>Tipo</th><th>IVA</th><th>Servicios</th><th>Acciones</th></tr></thead><tbody>
<?php foreach($rows as $r){ ?><tr><td><a href="ver_familia.php?familia=<?=(int)$r['id_tipo_iva']?>"><?=app_escape($r['categoria'])?></a></td><td><span class="neo-pill"><?=app_escape($r['nombre_tipo_cat']?:'Sin tipo')?></span></td><td class="number"><?=number_format((float)$r['porcentaje_iva']*100,2,',','.')?> %</td><td class="number"><?=(int)$r['servicios']?></td><td><div class="neo-actions"><a class="neo-button secondary" href="ver_familia.php?familia=<?=(int)$r['id_tipo_iva']?>">Ver servicios</a><a class="neo-button secondary" href="modificar_familia.php?familia=<?=(int)$r['id_tipo_iva']?>">Editar</a><a class="neo-button secondary" href="nuevo_articulo.php?familia=<?=(int)$r['id_tipo_iva']?>">+ Servicio</a><?php if(!(int)$r['servicios']){ ?><form method="post" action="eliminar_familia.php?familia=<?=(int)$r['id_tipo_iva']?>" data-confirm="¿Eliminar esta familia vacía?"><input type="hidden" name="_csrf" value="<?=app_csrf_token()?>"><button class="danger">Eliminar</button></form><?php } ?></div></td></tr><?php } ?>
<?php if(!$rows){ ?><tr><td colspan="5" class="neo-empty">Todavía no hay familias de servicios. Crea la primera para organizar tus tarifas.</td></tr><?php } ?></tbody></table></div>
<?php neo_page_end();
